import { gameClassForSeed } from "@/game/config/game-classes";

describe("customized test seeds", () => {
  it("uses the Warrior for the exact end-to-end test seed", () => {
    expect(gameClassForSeed("test").id).toBe("warrior");
  });
  test.each([
    ["testwarrior", "warrior"],
    ["testthief", "thief"],
    ["testcleric", "cleric"],
  ])("seed %s selects %s", (seed, expectedClass) => {
    expect(gameClassForSeed(seed).id).toBe(expectedClass);
  });

  it("lets an explicit class choice override an ordinary seed", () => {
    expect(gameClassForSeed("replayable-seed", "cleric").id).toBe("cleric");
  });

  it("keeps ordinary seed class selection reproducible", () => {
    expect(gameClassForSeed("replayable-seed").id).toBe(
      gameClassForSeed("replayable-seed").id,
    );
  });
});
